#include <iostream>

int main() {
    int equipos{2};
    int herramientas{3};
    int total{0};
    for (int equipo{1}; equipo <= equipos; ++equipo) {
        int revisadas{0};
        for (int herramienta{1}; herramienta <= herramientas; ++herramienta) {
            if (herramienta <= equipo) {
                ++revisadas;
                ++total;
                std::cout << "Revision=" << equipo << ":" << herramienta << "\n";
            }
        }
        std::cout << "Equipo=" << equipo << ";Revisadas=" << revisadas << "\n";
    }
    std::cout << "Total=" << total;
    return 0;
}

